--
-- Table structure for table `lingxing_automation_request_registry`
--

DROP TABLE IF EXISTS `lingxing_automation_request_registry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lingxing_automation_request_registry` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `registration_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '唯一注册编码',
  `automation_job_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联 automation_job.job_code',
  `task_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对应 LingxingTaskHandler.taskType()',
  `task_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求任务名称',
  `enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 停用，1 启用',
  `schedule_type` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT 'MANUAL/DAILY/WEEKLY/FIXED_DELAY',
  `run_time` time DEFAULT NULL COMMENT '每日/每周基准执行时间',
  `day_of_week` tinyint DEFAULT NULL COMMENT 'ISO 星期 1-7，仅 WEEKLY 使用',
  `fixed_delay_seconds` int DEFAULT NULL COMMENT '固定延迟秒数，仅 FIXED_DELAY 使用',
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Asia/Shanghai',
  `priority` int NOT NULL DEFAULT '0' COMMENT '生成请求任务的队列优先级',
  `slot_group` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DEFAULT' COMMENT '错峰分组',
  `slot_order` int NOT NULL DEFAULT '0' COMMENT '同组槽位序号，从 0 开始',
  `minimum_gap_seconds` int NOT NULL DEFAULT '60' COMMENT '槽位间最小间隔',
  `payload_template_json` json DEFAULT NULL COMMENT '生成 lingxing_request_task 时使用的载荷模板',
  `next_run_at` datetime DEFAULT NULL COMMENT '下一次生成请求任务时间',
  `last_enqueued_at` datetime DEFAULT NULL,
  `last_task_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SCHEDULED/PENDING/RUNNING/SUCCESS/FAILED/DISABLED',
  `last_error` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retry_limit` int NOT NULL DEFAULT '0',
  `remark` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lingxing_auto_registry_code` (`registration_code`),
  KEY `idx_lingxing_auto_registry_due` (`enabled`,`deleted`,`next_run_at`,`priority`),
  KEY `idx_lingxing_auto_registry_job` (`automation_job_code`,`enabled`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='领星自动化请求注册与排期';
/*!40101 SET character_set_client = @saved_cs_client */;

