  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `run_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Stable run id',
  `run_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SNAPSHOT / TARGET_POOL / WEEKLY / MONTHLY',
  `marketplace` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'UK / DE / ALL',
  `mid` int DEFAULT NULL COMMENT 'Lingxing marketplace id',
  `start_date` date DEFAULT NULL COMMENT 'Data window start',
  `end_date` date DEFAULT NULL COMMENT 'Data window end',
  `snapshot_week` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'yyyy-Www',
